"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["62749"],{42427(e){e.exports=JSON.parse('{"id":"F143","slug":"lease-liability-pv","name":"Lease Liability and First-Year Expense (IFRS 16 / ASC 842)","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Leases accounting (IFRS 16 / ASC 842)","level":"Intermediate","aliases":["right of use asset","operating lease","finance lease","lease accounting"],"formula":{"latex":"L_{0}=\\\\sum_{t=1}^{n}\\\\frac{P}{(1+r)^{t}},\\\\quad \\\\text{Interest}_{1}=r\\\\,L_{0},\\\\quad \\\\text{Depreciation}=\\\\frac{ROU}{n}","also":[],"text":"Lease liability = Present value of the lease payments at the discount rate; Year-1 interest = Rate x Liability; Depreciation = Right-of-use asset / Lease term; IFRS 16 expense = Interest + Depreciation"},"symbols":[{"symbol":"P","meaning":"Annual lease payment, paid at year end","unit":"money"},{"symbol":"r","meaning":"Discount rate: the rate implicit in the lease or the lessee\'s borrowing rate","unit":"per year"},{"symbol":"n","meaning":"Lease term in years","unit":"years"},{"symbol":"ROU","meaning":"Right-of-use asset, equal to the liability at the start","unit":"money"}],"when_to_use":"Use it to see how leases appear on the balance sheet. The lessee records a liability and a right-of-use asset at the present value of the payments. Under IFRS 16 (and ASC 842 finance leases) the expense is interest plus depreciation, which is higher in early years. Under ASC 842 an operating lease keeps a single straight-line expense.","worked_example":{"problem":"A company signs a 5-year lease with payments of 100 at the end of each year. The discount rate is 6%.","inputs":{"pay":100,"r":6,"n":5},"steps":[{"label":"Liability = payment x [1 - (1 + r)^-n] / r","working":"100 x (1-(1+0.06)^(-5)) / 0.06","value":"421.24"},{"label":"Year-1 interest = r x liability","working":"0.06 x 421.236","value":"25.27"},{"label":"Year-1 depreciation = liability / n","working":"421.236 / 5","value":"84.25"},{"label":"IFRS 16 year-1 expense = interest + depreciation","working":"25.2742+84.2473","value":"109.52"},{"label":"Liability at the end of year 1 = liability + interest - payment","working":"421.236+25.2742-100","value":"346.51"}],"answer":"The lease liability and the right-of-use asset start at 421.24. In year one the interest is 25.27 and depreciation is 84.25, so the IFRS 16 expense is 109.52 compared with the cash payment of 100. The expense is front-loaded: it is above the payment early on and below it near the end."},"calculator":{"available":true,"inputs":[{"id":"pay","label":"Annual lease payment","unit":"money","type":"number","default":100,"hint":""},{"id":"r","label":"Discount rate","unit":"%","type":"number","default":6,"hint":""},{"id":"n","label":"Lease term","unit":"years","type":"number","default":5,"hint":"","min":1}],"checks":[{"expr":"r>0","message":"The discount rate must be above zero."}],"steps":[{"id":"l0","label":"Liability = payment x [1 - (1 + r)^-n] / r","expr":"pay*(1-(1+r)^(-n))/r","format":"money"},{"id":"int1","label":"Year-1 interest = r x liability","expr":"r*l0","format":"money"},{"id":"dep","label":"Year-1 depreciation = liability / n","expr":"l0/n","format":"money"},{"id":"exp1","label":"IFRS 16 year-1 expense = interest + depreciation","expr":"int1+dep","format":"money"},{"id":"l1","label":"Liability at the end of year 1 = liability + interest - payment","expr":"l0+int1-pay","format":"money"}],"results":["l0","exp1"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"l0":421.23637855657165,"int1":25.2741827133943,"dep":84.24727571131433,"exp1":109.52145842470863}},"finder":{"finds":"The lease liability and first-year expense","needs":"Payment, discount rate, term"},"related":[{"slug":"adjusted-leverage-off-balance","name":"Adjusted Leverage with Off-Balance-Sheet Items"},{"slug":"pv-ordinary-annuity","name":"Present Value of an Ordinary Annuity"},{"slug":"net-advantage-to-leasing","name":"Net Advantage to Leasing (Lease vs. Buy)"}],"related_ids":["F142","F019","F159"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>L</mi><mn>0</mn></msub><mo>=</mo><munderover><mo>\u2211</mo><mrow><mi>t</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></munderover><mfrac><mi>P</mi><mrow><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\\"false\\">)</mo><mi>t</mi></msup></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mtext>Interest</mtext><mn>1</mn></msub><mo>=</mo><mi>r</mi><mtext>\u2009</mtext><msub><mi>L</mi><mn>0</mn></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Depreciation</mtext><mo>=</mo><mfrac><mrow><mi>R</mi><mi>O</mi><mi>U</mi></mrow><mi>n</mi></mfrac></mrow><annotation encoding=\\"application/x-tex\\">L_{0}=\\\\sum_{t=1}^{n}\\\\frac{P}{(1+r)^{t}},\\\\quad \\\\text{Interest}_{1}=r\\\\,L_{0},\\\\quad \\\\text{Depreciation}=\\\\frac{ROU}{n}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"lbo-sources-and-uses","name":"LBO Sources and Uses (Equity Check)"},"next":{"slug":"lc-discounting-cost","name":"Letter of Credit and Discounting: All-In Cost"},"lesson":null,"total":522}')}}]);